const c = $input.first().json;
const days = Number(c.lookback_days) || 7;
const since = new Date(Date.now() - days * 864e5);
const iso = since.toISOString();
return [{ json: { ...c, sinceIso: iso, sinceSoql: iso.replace(/\.\d{3}Z$/, 'Z'), sinceDate: iso.slice(0, 10) } }];

const A = {
  acme:   { id: '001SAMPLE0001', name: 'Acme Clinic Group', revenue: 5000000, rating: 'Hot' },
  globex: { id: '001SAMPLE0002', name: 'Globex Health', revenue: 400000, rating: 'Warm' },
  initech:{ id: '001SAMPLE0003', name: 'Initech Care', revenue: 80000, rating: 'Cold' },
  umbrella:{ id: '001SAMPLE0004', name: 'Umbrella Labs', revenue: 300000, rating: 'Warm' }
};
const row = (source, messageId, a, subject, text) => ({ source, messageId, accountId: A[a].id, account: A[a], customerId: A[a].id, subject, text });
const rows = [
  row('Salesforce Case', '00001', 'globex', 'Invoice is wrong', 'Our March invoice shows 4,000 EUR instead of 400 EUR. Please call me on +1234567890. Thanks, Jane (user@example.com)'),
  row('Salesforce Case', '00002', 'initech', 'Cannot update payment method', 'Updating our billing details keeps failing with error 502.'),
  row('Jira', 'CX-101', 'globex', 'Calendar sync is slow', 'Syncing with Google Calendar takes 30+ seconds since the last release.'),
  row('Jira', 'CX-102', 'initech', 'Feature request: export', 'We need a bulk CSV export of appointments and an Outlook integration.'),
  row('Salesforce Case', '00003', 'acme', 'Renewal', 'We are evaluating a competitor and may not renew unless the reporting problems are fixed.'),
  row('Salesforce Case', '00004', 'initech', 'SSO setup', 'The SSO documentation is unclear and our new staff are confused about how to get started.'),
  row('Jira', 'CX-103', 'umbrella', 'Thanks', 'We love the new reminders feature and the training session was great.'),
  row('Salesforce Case', '00005', 'umbrella', 'More seats', 'We would like to add 50 seats. Can you send a proposal and schedule a call?'),
  row('Jira', 'CX-101', 'globex', 'Calendar sync is slow', 'Duplicate of the same ticket (should be dropped).'),
  row('Jira', 'CX-105', 'globex', '', 'ok'),
  row('Jira', 'CX-104', 'globex', 'Crash on export', 'The app crashes when exporting reports (error E-1042).'),
  row('Salesforce Case', '00006', 'initech', 'Rappels SMS', 'Les rappels SMS ne sont plus envoyes depuis la derniere mise a jour.')
];
return rows.map(r => ({ json: r }));

const cfg = $('Compute Time Window').first().json;
const get = (n) => { try { return $(n).all().map(i => i.json).filter(j => j && Object.keys(j).length && !j.error); } catch (e) { return []; } };
const adf = (n) => !n ? '' : typeof n === 'string' ? n : ((n.text || '') + ' ' + (Array.isArray(n.content) ? n.content.map(adf).join(' ') : ''));
const strip = (s) => String(s || '').replace(/<[^>]*>/g, ' ');
const redact = (s) => strip(s)
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[email]')
  .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')
  .replace(/\s+/g, ' ').trim().slice(0, 1000);

const threshold = Number(cfg.vip_arr_threshold) || 0;
const vipIds = new Set(String(cfg.vip_account_ids || '').split(',').map(s => s.trim()).filter(Boolean));
const accounts = {};
for (const a of get('Fetch Salesforce Accounts')) accounts[a.Id] = { id: a.Id, name: a.Name || '', revenue: Number(a.AnnualRevenue) || 0, rating: a.Rating || '' };

const raw = [];
if (cfg.use_sample_data) {
  for (const r of get('Sample Feedback (test)')) raw.push(r);
} else {
  for (const c of get('Fetch Salesforce Cases')) {
    raw.push({ source: 'Salesforce Case', messageId: c.CaseNumber || c.Id, accountId: c.AccountId || '', account: accounts[c.AccountId], customerId: c.AccountId || '', subject: c.Subject || '', text: c.Description || '' });
  }
  for (const t of get('Fetch Jira Tickets')) {
    const f = t.fields || t;
    const rep = f.reporter || {};
    raw.push({ source: 'Jira', messageId: t.key || t.id, accountId: '', customerId: String(rep.accountId || rep.displayName || ''), subject: f.summary || '', text: adf(f.description) });
  }
}

const sd = $getWorkflowStaticData('global');
const seen = new Set(sd.seen || []);
const batch = new Set();
const out = [];
for (const r of raw) {
  const key = r.source + ':' + r.messageId;
  if (seen.has(key) || batch.has(key)) continue;
  const text = redact((r.subject ? r.subject + '. ' : '') + r.text);
  if (text.length < 5) continue;
  batch.add(key);
  const a = r.account || {};
  const isVIP = vipIds.has(r.accountId) || (threshold > 0 && (a.revenue || 0) >= threshold) || a.rating === 'Hot';
  out.push({ json: { key, source: r.source, messageId: String(r.messageId), accountId: r.accountId || '', customerId: r.customerId || '', accountName: a.name || '', accountRevenue: a.revenue || 0, isVIP, text } });
  if (out.length >= (Number(cfg.max_items) || 200)) break;
}
return out;

const src = $('Normalize, Redact & Dedupe').all().map(i => i.json);
const j = $input.first().json;
let res = j.output !== undefined ? j.output : j.text;
if (typeof res === 'string') { try { res = JSON.parse(res); } catch (e) { res = []; } }
res = (res && res.results) || res;
if (!Array.isArray(res)) res = [];
const by = {};
for (const r of res) if (r && r.id) by[r.id] = r;
const cats = ['Performance / Bug', 'Feature Request', 'Billing', 'Onboarding', 'Sales / Engagement', 'Other'];
const normCat = (c) => {
  const s = String(c || '').toLowerCase();
  if (cats.map(x => x.toLowerCase()).includes(s)) return cats.find(x => x.toLowerCase() === s);
  if (/perform|bug|crash|error|slow|outage|defect/.test(s)) return 'Performance / Bug';
  if (/feature|request|enhancement|integration/.test(s)) return 'Feature Request';
  if (/bill|invoice|payment|pricing|contract/.test(s)) return 'Billing';
  if (/onboard|training|setup|adoption|documentation/.test(s)) return 'Onboarding';
  if (/sales|engage|renew|upsell|expansion|churn/.test(s)) return 'Sales / Engagement';
  return 'Other';
};
const clamp = (v, lo, hi, d) => { v = Number(v); return Number.isFinite(v) ? Math.min(hi, Math.max(lo, Math.round(v))) : d; };
const sd = $getWorkflowStaticData('global');
const seen = new Set(sd.seen || []);
const runDate = new Date().toISOString();
const out = src.map(f => {
  const r = by[f.key] || {};
  seen.add(f.key);
  return { json: { runDate, ...f, signal: f.text.slice(0, 160), category: normCat(r.category), theme: r.theme || '', sentiment: clamp(r.sentiment, -2, 2, 0), urgency: clamp(r.urgency, 1, 5, 1), churn_risk: r.churn_risk === true && /cancel|not renew|won.t renew|competitor|switch(ing)? to|terminate|leave|churn|r.sili|annul|quitter|kuendig|kündig|abbestell/i.test(f.text) } };
});
sd.seen = [...seen].slice(-3000);
return out;

const items = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global');
const prev = sd.lastCounts || {};
const route = { 'Performance / Bug': 'product', 'Feature Request': 'product', 'Billing': 'billing', 'Onboarding': 'onboarding', 'Sales / Engagement': 'csm', 'Other': 'csm' };
const groups = {};
for (const f of items) (groups[f.category] = groups[f.category] || []).push(f);
const out = [];
const counts = {};
const short = (s) => String(s).length > 140 ? String(s).slice(0, 137) + '...' : String(s);
for (const [category, arr] of Object.entries(groups)) {
  const count = arr.length;
  counts[category] = count;
  const avg = +(arr.reduce((s, x) => s + x.sentiment, 0) / count).toFixed(2);
  const churn = arr.filter(x => x.churn_risk).length;
  const vip = arr.filter(x => x.isVIP).length;
  const maxUrg = Math.max(...arr.map(x => x.urgency));
  const priority = (churn > 0 || vip > 0 || maxUrg >= 5 || avg <= -1.5) ? 'High' : (avg <= -0.5 || maxUrg >= 4) ? 'Medium' : 'Low';
  const top = [...arr].sort((a, b) => (b.churn_risk - a.churn_risk) || (b.isVIP - a.isVIP) || b.urgency - a.urgency || a.sentiment - b.sentiment).slice(0, 5);
  const examples = top.map(x => '[' + x.source + ' ' + x.messageId + '] ' + short(x.signal) + (x.accountName ? ' (' + x.accountName + ')' : ''));
  const topAcc = top.find(x => x.accountId);
  const base = { category, labelSlug: category.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), count, avgSentiment: avg, churnRisk: churn, vipCount: vip, priority, previousCount: prev[category] || 0, themes: [...new Set(arr.map(x => x.theme).filter(Boolean))].slice(0, 5), topAccountId: topAcc ? topAcc.accountId : '', examples, examplesText: examples.map(e => '- ' + e).join('\n') };
  const finalRoute = (category === 'Other' && priority === 'Low') ? 'none' : route[category];
  out.push({ json: { ...base, route: finalRoute } });
  if (priority === 'High' && route[category] !== 'csm') out.push({ json: { ...base, route: 'csm', escalation: true } });
}
sd.lastCounts = counts;
return out;

const cl = $input.all().map(i => i.json).filter(c => !c.escalation);
const cfg = $('Config').first().json;
const since = $('Compute Time Window').first().json.sinceDate;
const total = cl.reduce((s, c) => s + c.count, 0);
const color = { High: '#c0392b', Medium: '#e67e22', Low: '#27ae60' };
const esc = (s) => String(s).replace(/</g, '&lt;');
const rows = cl.sort((a, b) => b.count - a.count).map(c => {
  const d = c.count - c.previousCount;
  const arrow = d > 0 ? '&#9650; ' + d : d < 0 ? '&#9660; ' + (-d) : '-';
  return '<tr><td><b>' + esc(c.category) + '</b></td><td>' + c.count + ' (' + arrow + ')</td><td>' + c.avgSentiment + '</td><td style="color:' + color[c.priority] + '"><b>' + c.priority + '</b></td><td>' + c.examples.map(esc).join('<br>') + '</td></tr>';
}).join('');
const dry = cfg.dry_run ? ' <i>(dry run: no Jira issues or Salesforce tasks were created)</i>' : '';
const html = '<h2>Weekly Voice of Customer digest</h2><p>' + total + ' new feedback items since ' + since + '.' + dry + '</p><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px"><tr><th>Category</th><th>Items (change vs last run)</th><th>Avg sentiment (-2..2)</th><th>Priority</th><th>Top signals</th></tr>' + rows + '</table>';
const high = cl.filter(c => c.priority === 'High').length;
return [{ json: { to: cfg.csm_email, subject: 'Weekly VOC digest: ' + total + ' items, ' + high + ' high-priority topics', html } }];
